# 排序可视化演示台
algo = 1    # 1冒泡 2选择
round = 1   # 轮次

hide()
fill_rect(0, 130, 360, 30, "#1d4ed8")
if algo == 1:
    write("冒泡排序 · 第 " + round + " 轮（大的往后沉）", 0, 130, "#fff", 11)
if algo == 2:
    write("选择排序 · 第 " + round + " 轮（选最小放前面）", 0, 130, "#fff", 11)
vals0 = 5
vals1 = 3
vals2 = 8
vals3 = 1
vals4 = 6
a = vals0
b = vals1
c = vals2
d = vals3
e = vals4
sorted1 = 8
sorted2 = 8
sorted3 = 8
sorted4 = 8
if round == 4:
    sorted1 = 8
    sorted2 = 6
    sorted3 = 5
    sorted4 = 3
if round == 3:
    sorted1 = 8
    sorted2 = 8
    sorted3 = 6
    sorted4 = 5
if round == 2:
    sorted1 = 8
    sorted2 = 8
    sorted3 = 8
    sorted4 = 6
if round == 1:
    sorted1 = 8
    sorted2 = 8
    sorted3 = 8
    sorted4 = 8
i = 0
while i < 5:
    x = -140 + i * 70
    h = 10 + i * 8
    val = 5
    if i == 0:
        val = vals0
    if i == 1:
        val = vals1
    if i == 2:
        val = vals2
    if i == 3:
        val = vals3
    if i == 4:
        val = vals4
    if round == 2:
        if i == 0:
            val = 3
        if i == 1:
            val = 5
        if i == 2:
            val = 1
        if i == 3:
            val = 6
        if i == 4:
            val = 8
    if round == 3:
        if i == 0:
            val = 1
        if i == 1:
            val = 3
        if i == 2:
            val = 5
        if i == 3:
            val = 6
        if i == 4:
            val = 8
    if round == 4:
        if i == 0:
            val = 1
        if i == 1:
            val = 3
        if i == 2:
            val = 5
        if i == 3:
            val = 6
        if i == 4:
            val = 8
    h = val * 9
    done = val >= sorted1
    if i >= 1:
        done = val >= sorted2
    if i >= 2:
        done = val >= sorted3
    if i >= 3:
        done = val >= sorted4
    if i == 4:
        done = 1
    col = "#f59e0b"
    if done == 1:
        col = "#16a34a"
    fill_rect(x, 20, 50, h, col)
    write(val, x, 20 + h / 2 + 26, "#0f172a", 10)
    i = i + 1
write("绿色=已就位；5 个数 4 轮内必然有序", -20, -40, "#7c3aed", 11)
write("比较次数：n(n-1)/2 —— 5 个数最多 10 次", -20, -66, "#0369a1", 10)

